/* Bounded original educational content; load after learning-data.js/course-data.js
 * and before learning-engine.js. This file only appends expansion data.
 * checked preserves the owner's source-verification date, not publication date.
 * UNESCO supplies ethical context, not evidence for the invented digital cases.
 * Historical examples are original analytical exercises, never historical quotations.
 * Cuba: related to the 1959–1965 inquiry; documented coverage here is 1959–1962.
 */
(()=>{const L=IBLearning.L; IBLearning.expansions=(IBLearning.expansions||[]).concat([
  {
    course:'digital',id:'digital-stakeholders',
    title:L('Actores, decisiones y responsabilidades','Stakeholders, decisions and responsibilities'),
    intro:L('Sigue el recorrido de una decisión automatizada y compara quién controla el sistema, quién depende de él y quién puede corregirlo. El caso de transporte es ficticio y original.','Trace an automated decision and compare who controls the system, who depends on it and who can correct it. The transport case is original and fictional.'),
    keywords:'sociedad digital actores partes interesadas stakeholders datos poder responsabilidad transporte automatización decisiones reclamación',difficulty:'foundation',
    goals:['Relacionar actores con decisiones y recursos concretos.','Explicar cómo un dato produce una consecuencia mediante reglas.','Diseñar una reclamación con autoridad y plazo de respuesta.'],
    prerequisites:'Distinguir datos de entrada, procesamiento y resultado de un sistema digital.',
    sections:[
      {title:'Un mapa de poder, además de una lista',body:'Identificar actores exige precisar qué pueden hacer. Una municipalidad decide el presupuesto; una empresa mantiene el programa; conductores aplican instrucciones; pasajeros dependen del servicio. No todos tienen igual capacidad para cambiar una regla o abandonar el sistema. Añade a cada actor una necesidad, un recurso y una decisión controlable. Una persona afectada puede no ser usuaria registrada: también importa quien queda fuera del servicio.'},
      {title:'Seguir datos hasta sus consecuencias',body:'Imagina una herramienta que propone frecuencias de autobuses a partir de validaciones electrónicas. El sensor registra viajes pagados, el servidor agrupa registros por franja horaria y una regla asigna vehículos. Ninguna etapa equivale automáticamente a medir necesidad. Si un lector falla, una ruta puede parecer vacía. El mecanismo conecta un registro incompleto con una recomendación y, finalmente, con una decisión presupuestaria humana. Señalar esa cadena permite localizar responsabilidades.'},
      {title:'Evaluar conflictos con criterios visibles',body:'La empresa puede preferir reducir costes mientras los pasajeros necesitan horarios estables. Compara tiempo de espera, cobertura y gastos, indicando quién soporta cada cambio. Una consulta sin posibilidad de modificar la propuesta aporta poca influencia. Diseña un canal de revisión: quién recibe el problema, qué evidencia examina y quién puede suspender una reducción. UNESCO ofrece contexto sobre participación y responsabilidad; no documenta este transporte ni certifica sus resultados.'}
    ],
    example:{title:'Caso ficticio original: la ruta del mercado',body:'En Puerto Claro, localidad inventada, un lector averiado registra cuarenta viajes donde un recuento manual autorizado observa ochenta durante la misma franja. La herramienta recomienda retirar un autobús. El equipo identifica primero el fallo de medición; no concluye todavía que toda la red necesite duplicar vehículos. Pasajeros y conductores solicitan mantener provisionalmente la frecuencia. La municipalidad puede hacerlo, mientras el proveedor repara el lector. Una nueva medición comparable permitiría revisar la recomendación. La solución distribuye tareas según capacidad real y evita responsabilizar al pasajero por un dato que nunca pudo corregir.'},
    extension:'Cambia una condición del caso: el contrato permite reparar sensores, pero solo la municipalidad puede modificar frecuencias. Explica por qué una respuesta rápida del proveedor no garantiza resolver la reclamación. Propón un registro público de decisiones con datos agregados y una fecha de revisión, sin publicar recorridos individuales.',
    mistakes:['Enumerar actores sin poder concreto: indicar qué decisión controla cada uno.','Tratar registros de uso como demanda total: investigar fallos y personas excluidas.'],
    glossary:[['Actor afectado','Persona o colectivo que recibe consecuencias aunque no gestione el sistema.'],['Responsabilidad operativa','Obligación concreta de revisar o corregir una parte del proceso.'],['Indicador indirecto','Medida que representa parcialmente una realidad distinta, como viajes registrados frente a necesidad.']],
    refs:[{name:'UNESCO · Ética de la IA: contexto de participación y responsabilidad; no fuente del caso ficticio',url:'https://www.unesco.org/en/artificial-intelligence/recommendation-ethics',scope:'context',checked:'2026-10-17'}],
    quiz:[
      {text:L('¿Qué relación del caso localiza mejor una responsabilidad?','Which relationship in the case best locates responsibility?'),options:[L('Todos desean un buen transporte.','Everyone wants good transport.'),L('La municipalidad puede suspender la reducción de frecuencia.','The municipality can suspend the frequency reduction.'),L('El sistema utiliza datos digitales.','The system uses digital data.')],answer:1,why:L('Una responsabilidad requiere conectar un actor con una decisión que pueda ejecutar.','Responsibility requires connecting an actor to a decision they can carry out.'),optionWhy:[L('Una aspiración compartida no identifica quién decide.','A shared aspiration does not identify the decision maker.'),L('Señala una autoridad concreta sobre la consecuencia discutida.','It identifies specific authority over the disputed consequence.'),L('Describe el medio técnico, no la capacidad de corregir.','It describes the technology, not the ability to correct it.')]},
      {text:L('¿Qué permite inferir el contraste de cuarenta registros y ochenta viajes observados?','What can be inferred from forty records versus eighty observed trips?'),options:[L('Toda la red necesita el doble de autobuses.','The whole network needs twice as many buses.'),L('Los pasajeros rechazaron el servicio.','Passengers rejected the service.'),L('El registro de esa franja no representa todos los viajes observados.','The records for that time slot do not represent all observed trips.')],answer:2,why:L('La comparación detecta una discrepancia delimitada, no una conclusión sobre toda la red.','The comparison detects a bounded discrepancy, not a conclusion about the whole network.'),optionWhy:[L('Extrapola una observación local sin evidencia adicional.','It extrapolates a local observation without further evidence.'),L('El recuento muestra uso; no establece motivos de rechazo.','The count shows use; it does not establish rejection motives.'),L('Mantiene el alcance de la evidencia y justifica revisar el sensor.','It respects the evidence’s scope and justifies checking the sensor.')]},
      {text:L('¿Qué mejora una consulta sobre horarios?','What improves consultation about timetables?'),options:[L('Vincular las observaciones a una revisión con responsable y plazo.','Link feedback to a review with an owner and deadline.'),L('Recoger opiniones sin que nadie pueda cambiar la decisión.','Collect opinions without anyone being able to change the decision.'),L('Publicar cada recorrido individual.','Publish every individual journey.')],answer:0,why:L('Participar adquiere efecto cuando existe una vía para revisar decisiones.','Participation gains effect when there is a route to revise decisions.'),optionWhy:[L('Hace verificable la respuesta institucional.','It makes the institutional response checkable.'),L('La consulta carecería de una vía de influencia definida.','Consultation would lack a defined route to influence.'),L('Expone información personal sin resolver quién decide.','It exposes personal information without resolving who decides.')]} 
    ],
    practice:{prompt:L('Construye un mapa de responsabilidades para la ruta ficticia del mercado.','Build a responsibility map for the fictional market route.'),steps:[L('Conecta sensor, registro, recomendación y cambio de frecuencia.','Connect the sensor, record, recommendation and frequency change.'),L('Asigna a tres actores una decisión y una obligación de respuesta.','Assign three stakeholders one decision and one response duty each.'),L('Propón un indicador y una fecha para revisar la decisión.','Propose an indicator and a date to review the decision.')],checks:[L('¿Incluí a alguien afectado que no controla el programa?','Did I include someone affected who does not control the software?'),L('¿Cada corrección tiene una persona o institución capaz de ejecutarla?','Does each correction have a person or institution able to implement it?')]}
  },
  {
    course:'digital',id:'digital-ai',
    title:L('Datos de entrenamiento y sesgo de selección','Training data and selection bias'),
    intro:L('Examina cómo una etiqueta, una muestra y una prueba pueden producir una apariencia engañosa de precisión. Los datos de selección de cursos son ficticios y originales.','Examine how a label, a sample and a test can create a misleading appearance of accuracy. The course-selection data are original and fictional.'),
    keywords:'inteligencia artificial IA AI dataset bias sesgo datos entrenamiento etiquetas selección muestra representatividad validación falsos negativos responsabilidad',difficulty:'intermediate',
    goals:['Distinguir sesgo de selección y error de etiquetado.','Calcular tasas comparables para grupos de distinto tamaño.','Relacionar una evaluación técnica con una decisión de uso.'],
    prerequisites:'Calcular porcentajes e identificar ejemplos de entrada y salida en un modelo predictivo.',
    sections:[
      {title:'La etiqueta define lo que se aprende',body:'Un modelo supervisado aprende relaciones entre características y una etiqueta de entrenamiento. Si la etiqueta es terminar un curso, no equivale necesariamente a tener capacidad para aprenderlo. Quien abandona por un horario incompatible puede quedar etiquetado como poco apto. Antes de aumentar datos, pregunta cómo se produjeron esas etiquetas, qué variable se pretende representar y qué decisiones históricas influyeron en los registros disponibles.'},
      {title:'Una muestra grande puede seguir incompleta',body:'Los registros de participantes anteriores omiten a quienes nunca pudieron inscribirse. Esa selección limita la población sobre la que se puede evaluar una predicción. Duplicar registros del mismo entorno no incorpora experiencias ausentes. Además, probar con los mismos ejemplos usados para entrenar puede exagerar el rendimiento. Reserva datos separados y examina condiciones de uso distintas, como cambios de horario, idioma o dispositivo. Ninguna cifra aislada garantiza una transferencia adecuada.'},
      {title:'Comparar errores y sus consecuencias',body:'Una tasa global puede ocultar diferencias. Un falso negativo excluye a alguien que cumplía el criterio; su coste depende de la decisión posterior. Compara tasas con denominadores pertinentes y tamaños de muestra visibles. Las diferencias orientan una investigación, pero no identifican por sí solas una causa. La revisión humana necesita información y autoridad para corregir; un operador que confirma todo sin examinar evidencia no constituye una revisión efectiva.'}
    ],
    example:{title:'Caso ficticio original: acceso a un taller',body:'Un taller inventado evalúa un selector con candidatos que cumplen un criterio independiente. Entre ochenta candidatos con conexión estable excluye erróneamente a cuatro; entre veinte con conexión intermitente excluye a seis. Las tasas son cinco y treinta por ciento, aunque el total de errores sea diez entre cien. El promedio oculta una diferencia relevante. El equipo investiga si entregas tardías se usaron como señal de capacidad, contrasta horarios y suspende la exclusión automática mientras revisa solicitudes. Estas cifras ilustran un razonamiento; no describen un sistema real ni prueban por sí solas la causa del sesgo.'},
    extension:'Diseña una prueba que pueda debilitar la hipótesis sobre conectividad: compara casos con condiciones semejantes y revisa cómo se asignaron las etiquetas. Especifica qué resultado te haría cambiar de explicación. Usa únicamente los datos ficticios; no recojas información personal para reproducir el ejercicio. UNESCO aporta contexto ético, no las cifras del caso.',
    mistakes:['Equiparar tamaño de muestra y representatividad: revisar quién está ausente.','Atribuir causalidad a una diferencia de tasas: investigar etiquetas y condiciones.'],
    glossary:[['Etiqueta','Resultado asignado a un ejemplo para entrenar o evaluar un modelo.'],['Sesgo de selección','Distorsión derivada de cómo se incorporan o excluyen casos de una muestra.'],['Falso negativo','Caso que cumple el criterio pero que el sistema clasifica como negativo.']],
    refs:[{name:'UNESCO · Ética de la IA: contexto de equidad y supervisión; no datos del ejercicio',url:'https://www.unesco.org/en/artificial-intelligence/recommendation-ethics',scope:'context',checked:'2026-10-17'}],
    quiz:[
      {text:L('¿Qué tasa de exclusión errónea presenta el grupo de veinte candidatos?','What erroneous-exclusion rate does the group of twenty candidates have?'),options:[L('6 %.','6%.'),L('30 %.','30%.'),L('10 %.','10%.')],answer:1,why:L('Seis errores entre veinte candidatos equivalen a 6/20 = 30 %.','Six errors among twenty candidates equal 6/20 = 30%.'),optionWhy:[L('Usa cien como denominador en lugar del tamaño del grupo.','It uses one hundred rather than the group size as the denominator.'),L('Relaciona los seis errores con los veinte casos pertinentes.','It relates the six errors to the twenty relevant cases.'),L('Diez por ciento es la tasa conjunta, no la de este grupo.','Ten percent is the combined rate, not this group’s rate.')]},
      {text:L('¿Por qué terminar un curso puede ser una etiqueta inadecuada de capacidad?','Why might course completion be an unsuitable label for ability?'),options:[L('Porque ninguna etiqueta puede utilizarse.','Because no label can ever be used.'),L('Porque todos los abandonos tienen la misma causa.','Because all withdrawals have the same cause.'),L('Porque los horarios y el acceso también pueden afectar la finalización.','Because timetables and access may also affect completion.')],answer:2,why:L('La variable observada puede combinar aprendizaje y condiciones externas.','The observed variable may combine learning and external conditions.'),optionWhy:[L('El problema exige examinar la validez de esta etiqueta, no descartar todas.','The issue calls for checking this label’s validity, not rejecting all labels.'),L('Supone precisamente la uniformidad que debe investigarse.','It assumes the very uniformity that needs investigation.'),L('Identifica una vía por la que la etiqueta puede representar otra cosa.','It identifies a way the label may represent something else.')]},
      {text:L('¿Qué demuestra directamente la diferencia entre 5 % y 30 %?','What does the difference between 5% and 30% directly establish?'),options:[L('Una desigualdad observada que requiere investigar su mecanismo.','An observed disparity whose mechanism needs investigation.'),L('Que la conectividad es la única causa.','That connectivity is the only cause.'),L('Que aumentar registros idénticos eliminará el problema.','That adding identical records will remove the problem.')],answer:0,why:L('Las tasas describen resultados; establecer causas requiere otras comparaciones.','Rates describe outcomes; establishing causes requires further comparisons.'),optionWhy:[L('Separa el resultado medido de su posible explicación.','It separates the measured outcome from its possible explanation.'),L('No se han descartado otras variables ni errores de etiquetado.','Other variables and labelling errors have not been ruled out.'),L('Repetir la misma selección puede conservar el sesgo.','Repeating the same selection may preserve the bias.')]} 
    ],
    practice:{prompt:L('Audita el selector ficticio del taller mediante una tabla de errores.','Audit the fictional workshop selector using an error table.'),steps:[L('Calcula tasas por grupo y la tasa conjunta, mostrando denominadores.','Calculate group rates and the combined rate, showing denominators.'),L('Propón dos explicaciones alternativas y una comprobación para distinguirlas.','Propose two alternative explanations and a check to distinguish them.'),L('Define qué decisiones suspender y quién revisaría los casos.','Define which decisions to suspend and who would review cases.')],checks:[L('¿Distingo una etiqueta observada del concepto que pretende medir?','Do I distinguish an observed label from the concept it is intended to measure?'),L('¿Evito presentar una diferencia estadística como una causa ya probada?','Do I avoid presenting a statistical difference as an established cause?')]}
  },
  {
    course:'digital',id:'digital-privacy',
    title:L('Privacidad y reconocimiento facial','Privacy and facial recognition'),
    intro:L('Relaciona captura, plantilla biométrica, comparación y decisión para evaluar una propuesta de reconocimiento facial. El escenario de biblioteca es ficticio y original.','Connect capture, biometric template, comparison and decision to evaluate a facial-recognition proposal. The library scenario is original and fictional.'),
    keywords:'privacidad privacy reconocimiento facial facial recognition biometría consentimiento minimización retención verificación identificación falsos positivos datos',difficulty:'intermediate',
    goals:['Distinguir verificación e identificación facial.','Separar seguridad de datos y justificación de su recogida.','Comparar alternativas según necesidad y consecuencias del error.'],
    prerequisites:'Entender que una imagen digital y un registro asociado pueden revelar información personal.',
    sections:[
      {title:'De la imagen a una comparación',body:'En un sistema facial, una cámara capta una imagen y un procedimiento extrae características para construir una representación numérica o plantilla. El sistema compara plantillas y aplica un umbral de similitud. Verificar pregunta si alguien corresponde a una identidad declarada; identificar busca una correspondencia entre varias identidades. Una coincidencia es una salida del procedimiento, no certeza infalible. Iluminación, posición y datos de entrenamiento pueden afectar la comparación.'},
      {title:'Privacidad durante todo el recorrido',body:'Pregunta qué se conserva: imágenes, plantillas, horarios o resultados de comparación. Borrar la fotografía no elimina necesariamente la plantilla ni el historial de entradas. El cifrado dificulta accesos no autorizados, pero no decide si era necesario recoger datos ni qué usos son aceptables. Delimita finalidad, acceso y conservación. Combinar registros de asistencia con préstamos puede revelar patrones que cada base separada mostraba de manera menos directa.'},
      {title:'Alternativas y capacidad de rechazar',body:'Una alternativa debe permitir acceder al servicio sin una penalización desproporcionada. Si rechazar biometría obliga a esperar una hora, la elección es materialmente desigual. Compara tarjeta, comprobación presencial y reconocimiento facial según el problema real. También identifica quién puede resolver una coincidencia incorrecta. El marco ético de UNESCO orienta preguntas sobre privacidad y proporcionalidad; no demuestra que una tecnología concreta sea necesaria ni sustituye una evaluación de su contexto.'}
    ],
    example:{title:'Caso ficticio original: entrar en una biblioteca',body:'La biblioteca inventada Brisa propone identificar visitantes frente a toda su base para acelerar el acceso. Sin embargo, solo necesita comprobar una reserva. Una tarjeta con código podría consultar esa reserva sin crear una plantilla facial. En una prueba imaginaria, una coincidencia errónea atribuye una visita a otra persona. Antes de sancionar, el personal debe verificar el registro y corregirlo. Borrar únicamente la foto dejaría pendiente la plantilla y la visita incorrecta. La comparación muestra dos preguntas distintas: cómo reducir errores y si recoger biometría resulta necesario para la finalidad declarada.'},
    extension:'Dibuja dos recorridos de datos: identificación facial y tarjeta de reserva. Marca en cada uno dónde se vincula una identidad, cuánto tiempo se guarda el registro y quién puede corregirlo. Justifica una elección según la necesidad del caso, sin afirmar que una alternativa es siempre superior en cualquier entorno.',
    mistakes:['Equiparar cifrado con privacidad completa: revisar finalidad, acceso y conservación.','Confundir coincidencia con identidad demostrada: comprobar errores y ofrecer revisión.'],
    glossary:[['Plantilla biométrica','Representación numérica derivada de características corporales para realizar comparaciones.'],['Verificación','Comparación con la identidad que una persona declara.'],['Identificación','Búsqueda de una posible correspondencia dentro de un conjunto de identidades.']],
    refs:[{name:'UNESCO · Ética de la IA: contexto de privacidad y proporcionalidad; caso original',url:'https://www.unesco.org/en/artificial-intelligence/recommendation-ethics',scope:'context',checked:'2026-10-17'}],
    quiz:[
      {text:L('Comparar un rostro con toda la base de visitantes es…','Comparing a face against the entire visitor database is…'),options:[L('Una identificación entre varias identidades posibles.','Identification among several possible identities.'),L('Una verificación de una única identidad declarada.','Verification of one declared identity.'),L('Una eliminación de datos.','Data deletion.')],answer:0,why:L('La búsqueda intenta establecer a quién corresponde el rostro dentro de un conjunto.','The search attempts to establish who the face belongs to within a set.'),optionWhy:[L('Describe la búsqueda entre múltiples candidatos.','It describes the search among multiple candidates.'),L('La verificación parte de una identidad declarada concreta.','Verification starts from a specific declared identity.'),L('Comparar registros no los elimina.','Comparing records does not delete them.')]},
      {text:L('Si se borra la fotografía, ¿qué debe comprobarse todavía?','If the photograph is deleted, what must still be checked?'),options:[L('Nada: toda la información desaparece siempre.','Nothing: all information always disappears.'),L('Si permanecen la plantilla y los registros vinculados.','Whether the template and linked records remain.'),L('Solo el color de la cámara.','Only the camera’s colour.')],answer:1,why:L('El sistema puede conservar representaciones y eventos derivados de la imagen.','The system may retain representations and events derived from the image.'),optionWhy:[L('Supone una eliminación que no se ha comprobado.','It assumes deletion that has not been checked.'),L('Examina datos distintos que pueden seguir identificando a la persona.','It examines separate data that may still identify the person.'),L('No responde a la conservación de información.','It does not address information retention.')]},
      {text:L('¿Qué pregunta aborda mejor la proporcionalidad en Brisa?','Which question best addresses proportionality at Brisa?'),options:[L('¿El sistema tiene una pantalla moderna?','Does the system have a modern screen?'),L('¿Puede conservar todas las visitas para siempre?','Can it retain all visits forever?'),L('¿Puede comprobarse la reserva con menos datos personales?','Can the reservation be checked using less personal data?')],answer:2,why:L('Compara el tratamiento de datos con lo necesario para cumplir la finalidad.','It compares data processing with what is necessary to achieve the purpose.'),optionWhy:[L('La apariencia no justifica recoger biometría.','Appearance does not justify collecting biometrics.'),L('La capacidad técnica de guardar no demuestra necesidad.','The technical ability to retain data does not establish necessity.'),L('Examina una alternativa vinculada al mismo objetivo.','It examines an alternative linked to the same objective.')]} 
    ],
    practice:{prompt:L('Compara dos formas de comprobar una reserva en la biblioteca ficticia.','Compare two ways of checking a reservation at the fictional library.'),steps:[L('Describe entradas, comparación, registros conservados y decisión para cada alternativa.','Describe inputs, comparison, retained records and decision for each alternative.'),L('Explica cómo corregir una atribución errónea sin impedir el acceso legítimo.','Explain how to correct a mistaken attribution without preventing legitimate access.')],checks:[L('¿Distingo necesidad de recogida y seguridad del almacenamiento?','Do I distinguish collection necessity from storage security?'),L('¿La alternativa permite rechazar biometría sin una carga desproporcionada?','Does the alternative allow refusal of biometrics without a disproportionate burden?')]}
  },
  {
    course:'digital',id:'digital-algorithms',
    title:L('Algoritmos, clasificación y decisiones','Algorithms, ranking and decisions'),
    intro:L('Calcula una clasificación y examina qué prioridades incorpora. La asignación de turnos es un ejercicio ficticio original, no un sistema observado.','Calculate a ranking and examine the priorities it encodes. The appointment allocation is an original fictional exercise, not an observed system.'),
    keywords:'algoritmos algorithms clasificación ranking ponderación reglas transparencia explicabilidad optimización umbral automatización',difficulty:'intermediate',
    goals:['Ejecutar una regla de puntuación con entradas explícitas.','Explicar cómo una ponderación cambia prioridades.','Proponer una revisión que examine reglas y consecuencias.'],
    prerequisites:'Multiplicar números decimales y distinguir una variable de entrada de un resultado.',
    sections:[
      {title:'Una regla ejecutable contiene elecciones',body:'Un algoritmo especifica operaciones para transformar entradas en resultados. Puede ordenar solicitudes mediante reglas fijadas por personas sin aprender de ejemplos: no todo algoritmo es inteligencia artificial. Para comprenderlo, identifica entradas, unidades, operaciones, condiciones y salida. Una regla puede ejecutarse correctamente y aun así servir mal al objetivo propuesto. Por ejemplo, ordenar por rapidez de envío es consistente, pero no demuestra que se atienda primero a quien más necesita el servicio. La evaluación debe separar corrección del cálculo y justificación de la prioridad.'},
      {title:'Ponderar cambia lo que cuenta',body:'Una puntuación combina variables mediante pesos. Antes de sumarlas, comprueba que sus escalas sean comparables: diez puntos de espera no significan diez días si alguien transformó previamente el registro. Escribe esa transformación y explica los pesos. Después cambia un peso manteniendo las entradas para observar la sensibilidad del orden. Un resultado inestable no es necesariamente incorrecto, pero exige justificar qué prioridad se eligió. También hace falta una regla para empates y para datos ausentes; tratarlos como cero puede perjudicar a quien no logró registrarlos.'},
      {title:'Del resultado a una decisión revisable',body:'Publicar una fórmula permite reproducir operaciones, pero no garantiza comprender sus consecuencias. Una explicación útil identifica qué dato influyó, cómo corregirlo y quién puede revisar la decisión. Compara también resultados para personas que no completaron la solicitud, pues quedan fuera de la clasificación visible. Documenta la versión de la regla y cuándo se aplicó. UNESCO aporta contexto ético sobre transparencia y responsabilidad en IA; aquí se adapta como pregunta de análisis, sin presentar este algoritmo elemental como un modelo de IA ni como caso documentado por UNESCO.'}
    ],
    example:{title:'Ejercicio resuelto original: dos solicitudes',body:'Un servicio ficticio usa dos escalas de cero a diez: espera E y urgencia U. Con P = 0,6E + 0,4U, la solicitud A, E = 8 y U = 2, obtiene 5,6; B, E = 4 y U = 7, obtiene 5,2. A queda primero. Al invertir los pesos, A obtiene 4,4 y B obtiene 5,8: B pasa delante. No cambió ninguna necesidad, sino la prioridad de la regla. Elegir un orden exige justificar el peso de espera y urgencia, además de comprobar las operaciones.'},
    extension:'Introduce una solicitud con urgencia desconocida. Compara asignarle cero, solicitar una revisión y posponerla. Explica qué información falta y qué consecuencia produciría cada tratamiento, sin convertir ausencia de datos en ausencia de necesidad.',
    mistakes:['Llamar IA a cualquier cálculo: distinguir reglas programadas y aprendizaje.','Confundir transparencia con justicia: una fórmula visible también exige justificar criterios.'],
    glossary:[['Ponderación','Peso asignado a una variable dentro de un cálculo.'],['Sensibilidad','Grado en que cambia un resultado al modificar entradas o supuestos.'],['Regla de desempate','Criterio adicional para ordenar resultados con igual puntuación.']],
    refs:[{name:'UNESCO · Transparencia y responsabilidad en IA; contexto ético, no fuente de la fórmula ficticia',url:'https://www.unesco.org/en/artificial-intelligence/recommendation-ethics',scope:'context',checked:'2026-10-18'}],
    quiz:[
      {text:L('¿Qué puntuación obtiene A con los pesos originales?','What score does A receive with the original weights?'),options:[L('5,6.','5.6.'),L('4,4.','4.4.'),L('10.','10.')],answer:0,why:L('0,6 × 8 + 0,4 × 2 = 4,8 + 0,8 = 5,6.','0.6 × 8 + 0.4 × 2 = 4.8 + 0.8 = 5.6.'),optionWhy:[L('Aplica ambos pesos a sus variables correspondientes.','It applies both weights to the corresponding variables.'),L('Es el resultado al invertir los pesos.','That is the result after reversing the weights.'),L('Suma las entradas sin aplicar ponderaciones.','It adds the inputs without applying weights.')]},
      {text:L('¿Por qué cambia el primer puesto al invertir los pesos?','Why does first place change when the weights are reversed?'),options:[L('Las solicitudes cambiaron sus datos.','The applications changed their data.'),L('La urgencia adquiere mayor peso relativo.','Urgency receives greater relative weight.'),L('Todo algoritmo aprende automáticamente.','Every algorithm learns automatically.')],answer:1,why:L('Las entradas permanecen iguales y cambia el criterio de prioridad.','The inputs stay the same while the priority criterion changes.'),optionWhy:[L('El ejercicio mantiene constantes las entradas.','The exercise holds inputs constant.'),L('Explica el mecanismo que favorece a B.','It explains the mechanism favouring B.'),L('Esta fórmula utiliza pesos fijados, sin entrenamiento.','This formula uses fixed weights without training.')]},
      {text:L('¿Qué revisión resulta más útil para una urgencia ausente?','Which review is most useful for a missing urgency value?'),options:[L('Suponer siempre que equivale a cero.','Always assume it equals zero.'),L('Ocultar la fórmula para evitar preguntas.','Hide the formula to avoid questions.'),L('Comprobar el dato y ofrecer una vía de corrección.','Check the data and provide a correction route.')],answer:2,why:L('Un dato ausente requiere un tratamiento explícito y revisable.','Missing data require explicit, reviewable treatment.'),optionWhy:[L('Confunde desconocimiento con una urgencia medida como nula.','It confuses missing knowledge with measured zero urgency.'),L('Impide examinar el problema sin resolverlo.','It prevents scrutiny without solving the problem.'),L('Permite revisar la entrada que afecta al resultado.','It allows review of the input affecting the result.')]} 
    ],
    practice:{prompt:L('Evalúa las dos ponderaciones del servicio ficticio.','Evaluate the fictional service’s two sets of weights.'),steps:[L('Reproduce las cuatro puntuaciones e indica el orden resultante.','Reproduce the four scores and state the resulting order.'),L('Justifica una prioridad y define un desempate.','Justify one priority and define a tie-break rule.'),L('Diseña una revisión para datos ausentes o incorrectos.','Design a review for missing or incorrect data.')],checks:[L('¿Distingo un cálculo correcto de una prioridad justificable?','Do I distinguish a correct calculation from a defensible priority?'),L('¿La persona afectada puede corregir una entrada?','Can the affected person correct an input?')]}
  },
  {
    course:'digital',id:'digital-access',
    title:L('Acceso digital y participación efectiva','Digital access and effective participation'),
    intro:L('Sigue una tarea desde la conexión hasta su finalización y localiza barreras distintas. El portal de becas y sus cifras son ficticios y originales.','Follow a task from connection to completion and locate different barriers. The scholarship portal and its figures are original and fictional.'),
    keywords:'acceso digital access brecha digital inclusión conectividad accesibilidad alfabetización coste participación diseño discapacidad',difficulty:'foundation',
    goals:['Distinguir conexión, uso y resultado efectivo.','Calcular tasas con denominadores adecuados.','Relacionar una barrera concreta con una intervención evaluable.'],
    prerequisites:'Calcular porcentajes sencillos y reconocer que una tarea digital tiene varias etapas.',
    sections:[
      {title:'Conectarse es solo una etapa',body:'La brecha digital puede aparecer entre disponer de conexión, poder utilizar un servicio y obtener un resultado útil. Un teléfono compartido no ofrece necesariamente tiempo suficiente para una entrevista en línea. Una tarifa disponible puede resultar costosa para descargar documentos. Identifica la tarea, el dispositivo, el tiempo y los recursos necesarios antes de afirmar que alguien tiene acceso. No atribuyas automáticamente un abandono a falta de interés: puede indicar una barrera que los registros del portal no explican por sí solos.'},
      {title:'Diseñar para capacidades y condiciones diversas',body:'Accesibilidad significa que personas con distintas capacidades puedan realizar la tarea; no equivale únicamente a disponer de internet. Examina etiquetas comprensibles, navegación mediante teclado, textos alternativos y mensajes de error útiles. La alfabetización digital y el idioma también influyen, pero una capacitación no corrige un botón imposible de activar. Relaciona cada propuesta con su mecanismo: guardar un borrador evita perder trabajo tras una desconexión; reducir archivos disminuye consumo de datos. Una alternativa presencial requiere horarios y ubicación utilizables para constituir una opción efectiva.'},
      {title:'Medir participación sin ocultar exclusiones',body:'Define primero la población elegible y después cuenta conexiones, solicitudes iniciadas y solicitudes completadas. Cada cociente responde a una pregunta diferente. Una tasa alta entre quienes llegaron al último paso puede ocultar a muchas personas que nunca entraron. Para evaluar una mejora, compara periodos y condiciones semejantes y busca otras explicaciones de cualquier cambio. UNESCO ofrece contexto sobre inclusión y alfabetización en el ámbito de IA, no estadísticas sobre este portal. Las medidas del ejercicio deben justificarse por las barreras descritas y comprobarse mediante resultados pertinentes.'}
    ],
    example:{title:'Ejercicio resuelto original: becas en Isla Verde',body:'En un grupo ficticio de cien personas elegibles, ochenta pueden conectarse, sesenta inician la solicitud y treinta la completan. La conectividad alcanza el 80 %, pero la finalización entre elegibles es 30 %. Entre quienes empiezan, termina el 50 %. Esos porcentajes no son intercambiables. Una prueba imaginaria identifica que el portal borra formularios cuando cae la conexión. Guardar borradores aborda esa barrera; comprar más publicidad no la corrige directamente. Todavía habría que investigar por qué veinte personas conectadas no iniciaron y por qué otras veinte no podían conectarse.'},
    extension:'Propón un indicador para evaluar el guardado de borradores y otro para el acceso inicial. Indica qué comparación necesitarías antes de atribuir cualquier mejora al cambio de diseño, y cómo evitarías recopilar datos personales innecesarios.',
    mistakes:['Usar conexiones como medida de éxito: comprobar finalización y población excluida.','Proponer la misma solución para toda barrera: identificar primero el mecanismo.'],
    glossary:[['Brecha digital','Desigualdad en recursos, capacidades o beneficios vinculados a tecnologías digitales.'],['Accesibilidad','Posibilidad de utilizar un servicio con diferentes capacidades y formas de interacción.'],['Denominador','Población de referencia con la que se calcula una proporción.']],
    refs:[{name:'UNESCO · Inclusión y alfabetización en IA; contexto, no estadísticas de acceso del caso',url:'https://www.unesco.org/en/artificial-intelligence/recommendation-ethics',scope:'context',checked:'2026-10-18'}],
    quiz:[
      {text:L('¿Qué porcentaje de personas elegibles completa la solicitud?','What percentage of eligible people completes the application?'),options:[L('80 %.','80%.'),L('50 %.','50%.'),L('30 %.','30%.')],answer:2,why:L('Treinta finalizaciones entre cien personas elegibles producen 30 %.','Thirty completions among one hundred eligible people give 30%.'),optionWhy:[L('Mide conectividad, no finalización.','It measures connectivity, not completion.'),L('Usa como denominador solo las sesenta personas que empiezan.','It uses only the sixty starters as the denominator.'),L('Mantiene como referencia toda la población elegible.','It uses the entire eligible population as the reference.')]},
      {text:L('¿Qué cambio responde directamente a perder formularios tras una desconexión?','Which change directly addresses losing forms after disconnection?'),options:[L('Guardar borradores recuperables.','Save recoverable drafts.'),L('Aumentar anuncios del portal.','Increase portal advertising.'),L('Cambiar el color del logotipo.','Change the logo colour.')],answer:0,why:L('Conservar el trabajo permite continuar tras recuperar la conexión.','Preserving work enables continuation when the connection returns.'),optionWhy:[L('Interviene sobre el mecanismo de pérdida descrito.','It addresses the described loss mechanism.'),L('Puede aumentar visitas sin conservar formularios.','It may increase visits without preserving forms.'),L('No modifica la conservación de los datos introducidos.','It does not change how entered data are preserved.')]},
      {text:L('¿Qué indica una subida de finalizaciones después del cambio?','What does an increase in completions after the change indicate?'),options:[L('Que ninguna otra condición pudo influir.','That no other condition could have mattered.'),L('Una mejora observada cuya causa requiere comparación.','An observed improvement whose cause requires comparison.'),L('Que toda la población tiene acceso.','That the entire population has access.')],answer:1,why:L('La secuencia temporal por sí sola no aísla el efecto del cambio.','Temporal sequence alone does not isolate the effect of the change.'),optionWhy:[L('Descarta alternativas sin examinarlas.','It dismisses alternatives without examining them.'),L('Distingue resultado y explicación causal.','It distinguishes outcome from causal explanation.'),L('Las finalizaciones no describen necesariamente a quienes nunca entran.','Completions do not necessarily describe those who never enter.')]} 
    ],
    practice:{prompt:L('Diseña una mejora de acceso para el portal ficticio de becas.','Design an access improvement for the fictional scholarship portal.'),steps:[L('Representa las cuatro cantidades y calcula dos tasas con denominadores explícitos.','Represent the four counts and calculate two rates with explicit denominators.'),L('Relaciona dos barreras posibles con intervenciones diferentes.','Connect two possible barriers with different interventions.'),L('Propón una comparación que permita evaluar una intervención.','Propose a comparison to evaluate one intervention.')],checks:[L('¿Incluyo a las personas que nunca llegan al portal?','Do I include people who never reach the portal?'),L('¿Mi indicador mide la barrera que intento reducir?','Does my indicator measure the barrier I aim to reduce?')]}
  },
  {
    course:'history',id:'nazi',
    title:L('Estado nazi: nombramiento, coerción y poder legislativo','Nazi state: appointment, coercion and legislative power'),
    intro:L('Analiza la concentración de poder en 1933 mediante hechos documentados y una explicación causal delimitada. El ejercicio es una interpretación original, no una cita histórica.','Analyse the concentration of power in 1933 through documented facts and a bounded causal explanation. The exercise is an original interpretation, not a historical quotation.'),
    keywords:'estado nazi nazismo hitler consolidación poder 1933 ley habilitante enabling act coerción parlamento Hindenburg autoritarismo',difficulty:'intermediate',
    goals:['Distinguir acceso al gobierno y consolidación de una dictadura.','Relacionar coerción y cambio institucional.','Evaluar el alcance de una ley como evidencia histórica.'],
    prerequisites:'Identificar ejecutivo, parlamento y constitución, y ubicar Alemania en el periodo de entreguerras.',
    sections:[
      {title:'Llegar al gobierno no explica todo el proceso',body:'Hindenburg nombró canciller a Hitler el 30 de enero de 1933. El USHMM distingue ese acceso al cargo de la posterior transformación de Alemania en dictadura. Para explicarlo, separa condiciones, decisiones y consecuencias: una crisis puede abrir posibilidades, pero no ejecuta por sí misma una política. Pregunta quién tomó una decisión y qué capacidad nueva produjo. Evita reconstruir enero como si todos los acontecimientos posteriores fueran inevitables. Una cronología adquiere valor explicativo cuando muestra cambios concretos de autoridad, además de enumerar nombres y fechas.'},
      {title:'Coerción y cambio institucional',body:'La Ley Habilitante, aprobada el 23 de marzo y publicada el 24 de marzo de 1933, permitió al gobierno legislar sin aprobación parlamentaria. El USHMM documenta intimidación y exclusión de diputados comunistas y socialdemócratas. Por tanto, la existencia de una votación no basta para describir libertad política. Como interpretación, puede argumentarse que la coerción alteró las condiciones de decisión y que la ley amplió la capacidad del ejecutivo. Son dos mecanismos relacionados; confundirlos impide explicar cómo una medida institucional pudo facilitar la eliminación de controles.'},
      {title:'Leer una norma sin confundirla con toda la realidad',body:'Una ley permite estudiar competencias y procedimientos, pero no mide por sí sola obediencia, apoyo popular o experiencias de las víctimas. Distingue el documento de época traducido en la página del museo y la explicación retrospectiva que lo acompaña. Para evaluar una afirmación, señala qué parte del material la sostiene y qué dato adicional exigiría. Un argumento sobre capacidad legislativa necesita evidencia diferente de uno sobre actitudes sociales. Esta distinción evita presentar una reforma formal como descripción completa del funcionamiento de un régimen o de sus consecuencias.'}
    ],
    example:{title:'Ejercicio resuelto original: de evidencia a argumento',body:'Pregunta: ¿basta el nombramiento de enero para explicar la concentración de poder? Primero, identifica que el nombramiento da acceso al cargo. Segundo, añade la eliminación del requisito de aprobación parlamentaria como cambio distinto. Tercero, interpreta que reducir ese control facilita decisiones posteriores. Conclusión delimitada: el acceso y la ampliación de facultades cumplen funciones diferentes en la explicación. No se deduce cuánto apoyo social existía ni que cada decisión posterior fuera inevitable. El razonamiento es didáctico; no reproduce palabras de un actor histórico.'},
    extension:'Redacta una objeción a una explicación basada exclusivamente en leyes: ¿qué evidencia buscarías sobre aplicación y resistencia? Indica qué conclusión permitiría esa evidencia y cuál seguiría fuera de su alcance.',
    mistakes:['Confundir nombramiento con consolidación completa: distinguir etapas y mecanismos.','Interpretar una votación como consentimiento libre: examinar exclusiones y coerción.'],
    glossary:[['Consolidación','Proceso por el que un gobierno refuerza su control y reduce desafíos a su autoridad.'],['Coerción','Uso o amenaza de fuerza para restringir decisiones ajenas.'],['Control institucional','Procedimiento que limita o revisa el ejercicio de una autoridad.']],
    refs:[{name:'USHMM · Ascenso nazi: nombramiento de enero y contingencia histórica; síntesis institucional',url:'https://encyclopedia.ushmm.org/content/en/article/the-nazi-rise-to-power',scope:'context',checked:'2026-10-18'},{name:'USHMM · Ley Habilitante: explicación histórica y traducción del documento de 1933',url:'https://encyclopedia.ushmm.org/content/en/article/the-enabling-act',scope:'context',checked:'2026-10-18'}],
    quiz:[
      {text:L('¿Qué distingue mejor enero de marzo de 1933?','What best distinguishes January from March 1933?'),options:[L('Enero eliminó automáticamente todos los controles.','January automatically removed all checks.'),L('El nombramiento dio acceso al cargo; la ley amplió facultades legislativas.','Appointment gave access to office; the act expanded legislative powers.'),L('Ambos acontecimientos fueron elecciones presidenciales.','Both events were presidential elections.')],answer:1,why:L('Acceso al ejecutivo y ampliación de sus competencias son cambios distintos.','Access to the executive and expansion of its powers are different changes.'),optionWhy:[L('Convierte una etapa en explicación completa sin demostrarlo.','It turns one stage into a complete explanation without evidence.'),L('Relaciona cada acontecimiento con su función institucional.','It connects each event with its institutional function.'),L('Confunde nombramiento y legislación con otro procedimiento.','It confuses appointment and legislation with a different procedure.')]},
      {text:L('¿Qué limita interpretar la aprobación como consentimiento libre?','What limits interpreting passage as free consent?'),options:[L('La intimidación y exclusión de opositores.','Intimidation and exclusion of opponents.'),L('La existencia de una fecha de publicación.','The existence of a publication date.'),L('Que el documento pueda traducirse.','That the document can be translated.')],answer:0,why:L('Las condiciones de participación importan para evaluar una votación.','Conditions of participation matter when evaluating a vote.'),optionWhy:[L('Afectan directamente a quién puede participar y en qué condiciones.','They directly affect who can participate and under what conditions.'),L('Publicar una ley no demuestra libertad de participación.','Publishing a law does not establish free participation.'),L('La traducción no determina las condiciones políticas de aprobación.','Translation does not determine the political conditions of passage.')]},
      {text:L('¿Qué no demuestra por sí solo un texto legal?','What does a legal text fail to establish on its own?'),options:[L('Las competencias que enuncia.','The powers it states.'),L('El procedimiento que dispone.','The procedure it specifies.'),L('El grado de apoyo de toda la población.','The level of support across the entire population.')],answer:2,why:L('Una norma no constituye una medición de actitudes sociales.','A law is not a measurement of social attitudes.'),optionWhy:[L('Las competencias expresas sí pueden estudiarse en el texto.','Express powers can be studied in the text.'),L('El procedimiento escrito es parte de su contenido verificable.','The written procedure is part of its verifiable content.'),L('Esta afirmación exige evidencia social adicional.','This claim requires additional social evidence.')]} 
    ],
    practice:{prompt:L('Explica cómo se relacionan coerción y cambio institucional en 1933.','Explain how coercion and institutional change relate in 1933.'),steps:[L('Selecciona dos hechos documentados y localiza su fuente.','Select two documented facts and locate their source.'),L('Conecta cada hecho con una capacidad o restricción concreta.','Connect each fact with a specific power or constraint.'),L('Formula una interpretación y una limitación de su alcance.','Formulate an interpretation and one limitation of its scope.')],checks:[L('¿Distingo el documento histórico del comentario del museo?','Do I distinguish the historical document from the museum’s commentary?'),L('¿Evito inferir apoyo universal a partir de una ley?','Do I avoid inferring universal support from a law?')]}
  },
  {
    course:'history',id:'cuba',
    title:L('Cuba: consolidación y presión exterior, 1959–1962','Cuba: consolidation and external pressure, 1959–1962'),
    intro:L('Relaciona supervivencia del gobierno, presión estadounidense y alianza soviética. Esta ficha aporta cobertura limitada de 1959–1962 a la pregunta sobre consolidación del poder de Castro en 1959–1965; no documenta 1963–1965.','Connect government survival, US pressure and the Soviet alliance. This topic provides limited coverage of 1959–1962 for the inquiry into Castro’s consolidation of power in 1959–1965; it does not document 1963–1965.'),
    keywords:'cuba consolidacion poder castro 1959 1965 consolidación 1959 1962 revolución batista bahía cochinos crisis misiles guerra fría soberanía',difficulty:'intermediate',
    goals:['Ordenar tres momentos de 1959–1962 sin extender indebidamente la cobertura.','Distinguir supervivencia, legitimidad y autonomía.','Evaluar la utilidad y los límites de una síntesis diplomática estadounidense.'],
    prerequisites:'Identificar Cuba, Estados Unidos y la Unión Soviética en el contexto de la Guerra Fría.',
    sections:[
      {title:'Del cambio de gobierno al problema de consolidación',body:'La caída de Batista en 1959 abrió paso al gobierno encabezado por Castro. La síntesis del Office of the Historian vincula expropiaciones de activos estadounidenses y acercamiento soviético con el deterioro de relaciones con Washington. Estos hechos sitúan una dimensión exterior del proceso. Consolidar poder, sin embargo, requiere preguntar también por instituciones, oposición y capacidad de gobernar. No conviertas una narración diplomática en prueba suficiente sobre toda la sociedad cubana. Esta ficha delimita su evidencia a 1959–1962, aunque la pregunta de estudio más amplia llegue hasta 1965.'},
      {title:'Una amenaza derrotada y una inferencia delimitada',body:'En abril de 1961, fuerzas cubanas derrotaron en Bahía de Cochinos a una fuerza de exiliados entrenada y financiada por la CIA. El Office of the Historian interpreta el fracaso de la invasión como fortalecimiento del gobierno de Castro. Distingue el desenlace militar de esa valoración sobre sus efectos. Para sostener un argumento sobre legitimidad interna harían falta indicadores adicionales, no solo la permanencia del gobernante. Pregunta qué desafío concreto fue neutralizado y evita concluir que desapareció toda oposición o que toda la población compartió una misma actitud.'},
      {title:'Protección y autonomía son criterios distintos',body:'En 1962, el acuerdo para instalar misiles soviéticos y la posterior crisis situaron a Cuba en una confrontación entre superpotencias. La resolución incluyó retirada de misiles y una garantía estadounidense de no invasión. Analíticamente, protección frente a una amenaza y autonomía para decidir no son equivalentes. Evalúa cada criterio por separado y pregunta quién participó en las decisiones decisivas. Las páginas citadas son síntesis retrospectivas de una institución estadounidense, no testimonios cubanos contemporáneos. Su perspectiva es relevante para estudiar política exterior, pero necesita contraste para responder preguntas sobre experiencias internas.'}
    ],
    example:{title:'Ejercicio resuelto original: precisar una tesis',body:'Una tesis inicial afirma que sobrevivir a una amenaza demuestra control absoluto. Para corregirla, define primero el resultado observado: el gobierno no fue derrocado por la invasión. Después separa una inferencia plausible, el refuerzo de su posición, de una afirmación no demostrada, la desaparición de todo desacuerdo. La conclusión revisada limita el argumento a supervivencia y posición frente a un desafío exterior. Para estudiar consentimiento o control institucional, propone otras fuentes. Este análisis no inventa una voz cubana ni atribuye a Castro declaraciones no verificadas.'},
    extension:'Diseña una investigación sobre 1963–1965 indicando dos preguntas y los tipos de documentos necesarios. Mantén esos años como pendientes de verificación: no completes la cronología con acontecimientos supuestos.',
    mistakes:['Confundir supervivencia con apoyo unánime: definir qué resultado demuestra la evidencia.','Extender hechos de 1962 a 1965: señalar el límite cronológico de las fuentes utilizadas.'],
    glossary:[['Supervivencia del gobierno','Continuidad en el poder frente a un intento de desplazamiento.'],['Legitimidad','Aceptación de una autoridad como justificada; requiere evidencia distinta de mera permanencia.'],['Autonomía','Capacidad de decidir sin depender decisivamente de otro actor.']],
    refs:[{name:'Office of the Historian · Bahía de Cochinos y consecuencias: síntesis retrospectiva estadounidense, 1959–1962; serie archivada',url:'https://history.state.gov/milestones/1961-1968/bay-of-pigs',scope:'context',checked:'2026-10-18'},{name:'Office of the Historian · Crisis de octubre de 1962: síntesis diplomática retrospectiva; serie archivada',url:'https://history.state.gov/milestones/1961-1968/cuban-missile-crisis',scope:'context',checked:'2026-10-18'}],
    quiz:[
      {text:L('¿Qué resultado permite afirmar directamente la derrota de la invasión?','What outcome can the invasion’s defeat directly establish?'),options:[L('El gobierno sobrevivió a ese intento de derrocamiento.','The government survived that overthrow attempt.'),L('Desapareció toda oposición interna.','All internal opposition disappeared.'),L('Toda la población apoyó cada política.','The entire population supported every policy.')],answer:0,why:L('Un desenlace militar permite una conclusión limitada sobre supervivencia.','A military outcome supports a bounded conclusion about survival.'),optionWhy:[L('Respeta el alcance del hecho documentado.','It respects the scope of the documented fact.'),L('Generaliza sobre actores no medidos por ese desenlace.','It generalises about actors not measured by that outcome.'),L('Infere actitudes universales sin evidencia social.','It infers universal attitudes without social evidence.')]},
      {text:L('¿Por qué distinguir protección y autonomía?','Why distinguish protection from autonomy?'),options:[L('Porque son palabras para el mismo resultado.','Because they describe the same outcome.'),L('Porque una alianza elimina necesariamente todo riesgo.','Because an alliance necessarily removes every risk.'),L('Porque reducir una amenaza no demuestra controlar las decisiones del aliado.','Because reducing a threat does not establish control over an ally’s decisions.')],answer:2,why:L('Los dos criterios evalúan dimensiones diferentes de una relación.','The two criteria evaluate different dimensions of a relationship.'),optionWhy:[L('Borra la diferencia entre seguridad y capacidad de decisión.','It erases the difference between security and decision-making capacity.'),L('Una alianza no garantiza ausencia de riesgo.','An alliance does not guarantee absence of risk.'),L('Permite evaluar resultados sin equiparar conceptos distintos.','It enables evaluation without equating distinct concepts.')]},
      {text:L('¿Cómo usar esta ficha para una pregunta sobre 1959–1965?','How should this topic be used for a question about 1959–1965?'),options:[L('Suponer que verifica todos los años del periodo.','Assume it verifies every year in the period.'),L('Usarla para 1959–1962 y verificar por separado 1963–1965.','Use it for 1959–1962 and verify 1963–1965 separately.'),L('Presentar las síntesis como diarios personales cubanos.','Present the summaries as Cuban personal diaries.')],answer:1,why:L('El alcance declarado termina en 1962 y las fuentes son retrospectivas.','The stated scope ends in 1962 and the sources are retrospective.'),optionWhy:[L('Confunde las palabras clave con cobertura documental completa.','It confuses keywords with complete documentary coverage.'),L('Conserva el límite cronológico y define el trabajo pendiente.','It preserves the chronological limit and defines the remaining work.'),L('Atribuye un origen y género que las fuentes no tienen.','It assigns an origin and genre the sources do not have.')]} 
    ],
    practice:{prompt:L('Construye una respuesta delimitada sobre presión exterior y consolidación en Cuba.','Build a bounded answer about external pressure and consolidation in Cuba.'),steps:[L('Ordena 1959, abril de 1961 y octubre de 1962 con un hecho por momento.','Order 1959, April 1961 and October 1962 with one fact for each.'),L('Separa hechos, interpretaciones y preguntas pendientes.','Separate facts, interpretations and outstanding questions.'),L('Indica qué evidencia faltaría para ampliar la respuesta hasta 1965.','State what evidence would be missing to extend the answer to 1965.')],checks:[L('¿Identifico la perspectiva institucional de las fuentes?','Do I identify the sources’ institutional perspective?'),L('¿Evito confundir supervivencia, legitimidad y autonomía?','Do I avoid confusing survival, legitimacy and autonomy?')]}
  },
  {
    course:'history',id:'newdeal',
    title:L('New Deal: reformas sociales y criterios de evaluación','New Deal: social reforms and evaluation criteria'),
    intro:L('Compara dos reformas de 1935 y distingue propósito, diseño y resultados. La lectura de la ley Wagner exige separar el original de sus enmiendas posteriores.','Compare two reforms of 1935 and distinguish purpose, design and outcomes. Reading the Wagner Act requires separating the original from later amendments.'),
    keywords:'new deal newdeal gran depresión Roosevelt 1935 social security act seguridad social Wagner national labor relations act reforma alivio recuperación sindicatos',difficulty:'intermediate',
    goals:['Comparar mecanismos de dos reformas del New Deal.','Separar evidencia normativa y evidencia de resultados.','Identificar el riesgo de atribuir enmiendas posteriores al texto de 1935.'],
    prerequisites:'Ubicar la Gran Depresión y distinguir una ley de una estadística sobre sus efectos.',
    sections:[
      {title:'Definir éxito antes de evaluarlo',body:'Evaluar el New Deal exige precisar si se estudia alivio inmediato, recuperación económica o reforma institucional. Son criterios relacionados, pero una evidencia no responde automáticamente a los tres. La Social Security Act de 1935 estableció prestaciones de vejez y programas de apoyo, incluyendo mecanismos de protección frente al desempleo. Esto permite investigar el diseño de una respuesta a riesgos sociales. No demuestra por sí solo que todas las personas recibieran cobertura ni que la depresión terminara. Una evaluación rigurosa fija población, indicador y periodo antes de emitir un juicio global.'},
      {title:'Dos mecanismos para problemas diferentes',body:'La ley Wagner de 1935 protegió la organización y negociación colectiva y estableció la National Labor Relations Board. Su mecanismo difiere de una prestación: modifica las reglas de relación entre trabajadores y empleadores. Compara qué riesgo aborda cada reforma, quién debe actuar y cómo se reclama su cumplimiento. La explicación institucional de National Archives indica exclusiones de cobertura laboral, como agricultura y gobierno. Por eso, un derecho reconocido para ciertos trabajadores no equivale a protección universal. Examinar límites permite matizar una conclusión sin negar la existencia del cambio normativo.'},
      {title:'Una página puede reunir versiones distintas',body:'National Archives identifica expresamente la transcripción de la NLRA como texto enmendado desde 1935. No atribuyas cada cláusula visible al Congreso de aquel año. Separa la imagen del documento original, la introducción histórica y la transcripción posterior; comprueba la versión pertinente antes de analizar una disposición concreta. El mismo cuidado vale para los resultados: una ley acredita un diseño, mientras registros de aplicación y series comparables permiten investigar efectos. Una conclusión sobre reforma institucional puede estar bien respaldada aunque una afirmación sobre recuperación total siga pendiente de evidencia económica adicional.'}
    ],
    example:{title:'Ejercicio resuelto original: una comparación defendible',body:'Pregunta: ¿basta crear una prestación para demostrar éxito económico general? Primero, clasifica la medida como diseño de protección social. Segundo, distingue el criterio de acceso efectivo del criterio de recuperación económica. Tercero, propone comprobar beneficiarios y cobertura para el primero, y empleo o producción para el segundo. La respuesta resultante sostiene que cambiar instituciones constituye un resultado específico, pero no sustituye la medición de todos los demás. No se inventan porcentajes, beneficiarios ni experiencias personales para completar la evaluación.'},
    extension:'Prepara una tabla con propósito, mecanismo, población y evidencia faltante para cada ley. Si eliges una cláusula de la transcripción enmendada, marca su fecha como pendiente hasta contrastarla con la versión histórica correspondiente.',
    mistakes:['Equiparar aprobación y resultado: buscar evidencia de aplicación y cobertura.','Leer el texto enmendado como original de 1935: comprobar procedencia y fecha de cada disposición.'],
    glossary:[['Reforma institucional','Cambio de reglas u organismos que estructura decisiones futuras.'],['Negociación colectiva','Negociación entre empleadores y representantes de trabajadores sobre condiciones laborales.'],['Enmienda','Modificación posterior de un texto normativo.']],
    refs:[{name:'National Archives · Social Security Act: documento de 1935, transcripción y contexto histórico',url:'https://www.archives.gov/milestone-documents/social-security-act',scope:'context',checked:'2026-10-18'},{name:'National Archives · NLRA de 1935: imagen original y contexto; la transcripción incorpora enmiendas posteriores',url:'https://www.archives.gov/milestone-documents/national-labor-relations-act',scope:'context',checked:'2026-10-18'}],
    quiz:[
      {text:L('¿Qué diferencia mejor los mecanismos de las dos reformas?','What best distinguishes the two reforms’ mechanisms?'),options:[L('Ambas son únicamente campañas publicitarias.','Both are only advertising campaigns.'),L('Ambas prueban por sí solas el fin de la depresión.','Both establish the end of the depression on their own.'),L('Una organiza protección social; la otra regula derechos de organización y negociación.','One organises social protection; the other regulates organising and bargaining rights.')],answer:2,why:L('Las reformas actúan mediante instrumentos institucionales diferentes.','The reforms operate through different institutional instruments.'),optionWhy:[L('Ignora las prestaciones y los derechos establecidos.','It ignores the benefits and rights established.'),L('Confunde diseño normativo con un resultado económico general.','It confuses statutory design with an overall economic outcome.'),L('Relaciona cada reforma con su forma de intervención.','It connects each reform with its form of intervention.')]},
      {text:L('¿Qué precaución requiere la transcripción de la NLRA enlazada?','What precaution does the linked NLRA transcript require?'),options:[L('Comprobar qué disposiciones pertenecen a 1935 y cuáles son posteriores.','Check which provisions belong to 1935 and which are later.'),L('Atribuir todas sus cláusulas al texto original.','Attribute all its clauses to the original text.'),L('Ignorar su aviso sobre enmiendas.','Ignore its amendment notice.')],answer:0,why:L('La página señala que la transcripción incorpora modificaciones posteriores.','The page states that the transcript incorporates later amendments.'),optionWhy:[L('Evita introducir disposiciones posteriores en un análisis de 1935.','It prevents introducing later provisions into an analysis of 1935.'),L('Puede producir anacronismos jurídicos.','It may produce legal anachronisms.'),L('Descarta información esencial sobre la versión del documento.','It discards essential information about the document version.')]},
      {text:L('¿Qué evidencia adicional sirve para estudiar cobertura efectiva?','What additional evidence helps study effective coverage?'),options:[L('Solo el título de la ley.','Only the law’s title.'),L('Registros de beneficiarios comparados con la población pertinente.','Beneficiary records compared with the relevant population.'),L('La fecha de consulta de una página.','The date a webpage was consulted.')],answer:1,why:L('La cobertura requiere relacionar acceso observado y población de referencia.','Coverage requires relating observed access to a reference population.'),optionWhy:[L('El título no mide a quienes recibieron protección.','The title does not measure who received protection.'),L('Permite investigar alcance y posibles exclusiones.','It enables investigation of reach and possible exclusions.'),L('Fecha la consulta, no los efectos históricos.','It dates the consultation, not the historical effects.')]} 
    ],
    practice:{prompt:L('Compara las reformas de 1935 usando un criterio explícito de éxito.','Compare the 1935 reforms using an explicit success criterion.'),steps:[L('Define si evaluarás reforma institucional, cobertura o recuperación.','Define whether you will evaluate institutional reform, coverage or recovery.'),L('Explica un mecanismo de cada ley y una limitación de la evidencia.','Explain one mechanism of each act and one evidence limitation.'),L('Comprueba la versión de cualquier disposición específica que utilices.','Check the version of any specific provision you use.')],checks:[L('¿Mi conclusión responde al criterio elegido?','Does my conclusion address the selected criterion?'),L('¿Evito tratar una transcripción enmendada como texto íntegro de 1935?','Do I avoid treating an amended transcript as the complete 1935 text?')]}
  },
  {
    course:'history',id:'mexico',
    title:L('Revolución mexicana: coaliciones, constitución y resultados','Mexican Revolution: coalitions, constitution and outcomes'),
    intro:L('Compara alianzas y objetivos revolucionarios y examina qué puede demostrar la Constitución de 1917. El ejercicio distingue cambios legales y aplicación social.','Compare revolutionary alliances and aims and examine what the 1917 Constitution can establish. The exercise distinguishes legal changes from social implementation.'),
    keywords:'méxico mexico revolución mexicana Madero Díaz Zapata Villa Carranza Obregón constitución 1917 artículos 27 123 tierra trabajo coaliciones',difficulty:'intermediate',
    goals:['Explicar por qué una alianza contra un adversario no implica un programa común.','Relacionar disposiciones constitucionales con ámbitos de reforma.','Distinguir cambio normativo y resultados sociales verificables.'],
    prerequisites:'Distinguir gobierno, coalición militar y constitución, y ubicar México a comienzos del siglo XX.',
    sections:[
      {title:'Un adversario común no produce objetivos idénticos',body:'La exposición de la Library of Congress contrapone el impulso democrático de Madero con la demanda zapatista de restitución de tierras en Morelos. Después de la caída de Huerta, la alianza entre opositores se fracturó: Villa y Zapata se vincularon al campo convencionista, frente a Carranza y Obregón. Estos hechos permiten cuestionar la idea de una revolución con una voluntad única. Analíticamente, distingue quién combate junto a quién de qué orden desea construir cada actor. Una coincidencia táctica puede desaparecer cuando cambia el adversario o se disputa el gobierno.'},
      {title:'La Constitución como evidencia de cambio',body:'La Constitución de 1917 incorporó disposiciones sobre educación, tierra y trabajo. La exposición relaciona el artículo 27 con reforma agraria y propiedad nacional del subsuelo, y el 123 con derechos laborales, incluida organización y huelga. Esto documenta ámbitos del proyecto constitucional, no una ejecución uniforme e inmediata. Compara objetivos y disposiciones sin atribuir a todos los actores autoría o acuerdo idénticos. Una demanda puede influir en la agenda sin que quien la defendió controle el gobierno. Para analizar una cláusula concreta, distingue la reproducción histórica del texto y la explicación curatorial.'},
      {title:'Elegir un cierre exige explicar el criterio',body:'Una constitución puede funcionar como hito de reorganización institucional sin resolver todas las preguntas sobre conflicto y desigualdad. Si se toma 1917 como punto de llegada, explica que el criterio es constitucional; para evaluar resultados sociales hacen falta otras fechas e indicadores. Pregunta qué cambió, para quién y en qué lugar. La distribución efectiva de tierras exige registros diferentes de una norma sobre propiedad. Del mismo modo, reconocer derechos laborales no permite contar automáticamente trabajadores protegidos. Mantener esta distinción ayuda a formular conclusiones proporcionadas y evita convertir un hito jurídico en prueba de transformación total.'}
    ],
    example:{title:'Ejercicio resuelto original: revisar una conclusión',body:'Una respuesta inicial sostiene que aprobar derechos resuelve todas las demandas. Primero, identifica el salto entre reconocimiento y cumplimiento. Segundo, limita la conclusión a que el texto establece un marco de reforma. Tercero, propone contrastar expedientes de reparto para estudiar tierra y registros de conflictos para estudiar aplicación laboral. La respuesta revisada permite reconocer cambio institucional sin inventar una medida de éxito social. No describe a una familia real ni afirma haber consultado expedientes que no se han proporcionado.'},
    extension:'Compara dos posibles cierres de una investigación: aprobación constitucional y aplicación local de una reforma. Explica cómo cambiarían la pregunta, las fuentes necesarias y el alcance de la conclusión, sin suponer resultados locales.',
    mistakes:['Tratar a todos los revolucionarios como un bloque: separar alianzas y objetivos.','Equiparar constitución y cumplimiento: buscar evidencia de aplicación con lugar y fecha.'],
    glossary:[['Coalición','Alianza de actores que cooperan sin compartir necesariamente todos sus objetivos.'],['Restitución agraria','Devolución de tierras reclamadas como previamente despojadas.'],['Periodización','División del tiempo histórico según criterios explícitos de cambio y continuidad.']],
    refs:[{name:'Library of Congress · Panorama de la Revolución: síntesis curatorial sobre actores y conflictos',url:'https://www.loc.gov/exhibits/mexican-revolution-and-the-united-states/overview.html',scope:'context',checked:'2026-10-18'},{name:'Library of Congress · Constitución de 1917: explicación curatorial y reproducción del documento histórico',url:'https://www.loc.gov/exhibits/mexican-revolution-and-the-united-states/constitution-of-1917.html',scope:'context',checked:'2026-10-18'}],
    quiz:[
      {text:L('¿Qué demuestra una alianza contra un adversario común?','What does an alliance against a common opponent establish?'),options:[L('Que todos comparten un programa completo.','That everyone shares a complete programme.'),L('Que cooperan en ese contexto, aunque puedan discrepar sobre otros objetivos.','That they cooperate in that context, although they may disagree on other aims.'),L('Que nunca competirán por el gobierno.','That they will never compete for government.')],answer:1,why:L('Cooperación táctica y acuerdo programático son relaciones diferentes.','Tactical cooperation and programmatic agreement are different relationships.'),optionWhy:[L('Atribuye una unidad que debe investigarse.','It assumes a unity that must be investigated.'),L('Limita la inferencia a la cooperación observada.','It limits the inference to the observed cooperation.'),L('Predice permanencia sin evidencia sobre decisiones futuras.','It predicts permanence without evidence about future decisions.')]},
      {text:L('¿Qué correspondencia refleja los ámbitos estudiados?','Which pairing reflects the areas studied?'),options:[L('Artículo 27: tierra; artículo 123: trabajo.','Article 27: land; Article 123: labour.'),L('Artículo 27: trabajo; artículo 123: tierra.','Article 27: labour; Article 123: land.'),L('Ambos artículos solo regulan elecciones presidenciales.','Both articles only regulate presidential elections.')],answer:0,why:L('La exposición distingue reforma agraria y derechos laborales.','The exhibition distinguishes agrarian reform from labour rights.'),optionWhy:[L('Relaciona correctamente los artículos con sus ámbitos.','It correctly connects the articles with their areas.'),L('Invierte las correspondencias.','It reverses the pairings.'),L('Sustituye los ámbitos sociales por un objeto diferente.','It replaces the social areas with a different subject.')]},
      {text:L('¿Qué haría más sólida una afirmación sobre aplicación de una reforma agraria?','What would strengthen a claim about implementation of agrarian reform?'),options:[L('Repetir solamente el número del artículo.','Repeat only the article number.'),L('Suponer que aprobación significa cumplimiento total.','Assume adoption means complete implementation.'),L('Contrastar registros de reparto para un lugar y periodo definidos.','Compare distribution records for a defined place and period.')],answer:2,why:L('La implementación requiere evidencia de acciones y resultados situados.','Implementation requires evidence of actions and outcomes in context.'),optionWhy:[L('Identifica una norma sin mostrar su aplicación.','It identifies a rule without showing its application.'),L('Presupone el resultado que se quiere demostrar.','It assumes the outcome the claim seeks to establish.'),L('Permite investigar el cambio efectivo con un alcance preciso.','It enables investigation of actual change within a precise scope.')]} 
    ],
    practice:{prompt:L('Construye una comparación entre objetivos revolucionarios y cambio constitucional.','Build a comparison between revolutionary aims and constitutional change.'),steps:[L('Distingue dos actores, sus objetivos y una relación de alianza o conflicto.','Distinguish two actors, their aims and one relationship of alliance or conflict.'),L('Conecta una disposición constitucional con un ámbito de reforma.','Connect a constitutional provision with an area of reform.'),L('Formula una conclusión normativa y señala qué evidencia falta sobre aplicación.','Formulate a conclusion about the legal framework and identify missing implementation evidence.')],checks:[L('¿Evito atribuir objetivos idénticos a toda la coalición?','Do I avoid assigning identical aims to the whole coalition?'),L('¿Explico por qué elegí el cierre cronológico?','Do I explain my choice of chronological endpoint?')]}
  },
]);})();
